    var FileUtils = require("file/FileUtils");

    /**
     * @constructor
     */
    function FileIndex() {
        this._index = {};
        this._doNotRemoveItems = {};
    }

    /**
     * Master index
     * @private
     * @type {Object.<string, File|Directory>} Maps a fullPath to a File or Directory object
     */
